function searchPlaybooks(q = "", limit = 80) {
  const s = String(q || "").toLowerCase();
  let rows = PLAYBOOKS;
  if (s) rows = rows.filter(p => `${p.region} ${p.sector} ${p.name} ${p.trigger} ${p.buyer} ${p.deliverable}`.toLowerCase().includes(s));
  return rows.slice(0, Number(limit) || 80);
}

module.exports = { PLAYBOOKS, searchPlaybooks };
